<template><div class="space-y-4"><div class="grid gap-3 md:grid-cols-2"><el-input v-model="name" placeholder="动画名称"/><el-input-number v-model="duration" :min="0.1" :step="0.1"/><el-select v-model="timing"><el-option v-for="x in ['ease','linear','ease-in-out']" :key="x" :label="x" :value="x"/></el-select><el-input v-model="fromTransform" placeholder="起始 transform"/><el-input v-model="toTransform" placeholder="结束 transform"/></div><div class="rounded-xl p-8 text-center bg-blue-100 dark:bg-blue-900/30"><div class="mx-auto h-16 w-16 rounded-lg bg-blue-500" :style="previewStyle"/></div><el-button type="primary" size="small" @click="generate">生成 CSS</el-button><el-input v-model="css" type="textarea" :rows="8" readonly/></div></template>
<script setup lang="ts">import { ref,computed } from 'vue';const name=ref('slideIn');const duration=ref(1);const timing=ref('ease');const fromTransform=ref('translateX(-20px)');const toTransform=ref('translateX(0)');const css=ref('');const previewStyle=computed(()=>({animation:`${name.value} ${duration.value}s ${timing.value} infinite alternate`}));const generate=()=>{css.value=`@keyframes ${name.value} {\n  from { transform: ${fromTransform.value}; }\n  to { transform: ${toTransform.value}; }\n}\n\n.animated { animation: ${name.value} ${duration.value}s ${timing.value}; }`}</script>
